import{_ as r,l as i,o as e,c as d,v as t,p as n,x as o,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"可用表达式","description":"","frontmatter":{"title":"可用表达式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/available-expr.md","filePath":"cs/available-expr.md","lastUpdated":1789023840000}'),h={name:"cs/available-expr.md"};function E(_,a,m,B,u,b){const l=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="可用表达式" tabindex="-1">可用表达式 <a class="header-anchor" href="#可用表达式" aria-label="Permalink to &quot;可用表达式&quot;">​</a></h1><div class="epigraph"><p>表达式 $x\\,\\mathrm{op}\\,y$ 在 $p$ 可用，当从入口到 $p$ 的**每条**路都已算过它，且之后操作数没被改写。汇合是交。</p><footer>—— 据龙书第 9 章整理</footer></div><p>上一课<a href="/cs/reaching-def">到达定义</a>是前向并，回答哪次写还活着。本课不重编号定值。缺口是公共子表达式消除（CSE）要的另一判断：这里能不能<strong>重用</strong>已经算过的 \\(t\\leftarrow a+b\\)，而不必再算。必须所有路都算过，故交汇合；任一操作数被赋值则杀掉。后课指令选择在虚拟名 IR 上盖模板，可用集已尽量把重复运算收掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>e</code> 在块内被计算则 <code>gen</code>；块内对 \\(a\\) 或 \\(b\\) 赋值则 <code>kill</code> 所有含该操作数的表达式。方程：<code>in[B]=\\bigcap_{前驱} out[P]</code>（入口块 <code>in=\\emptyset</code>），<code>out[B]=gen[B]\\cup(in[B]-kill[B])</code>。从「全集合」或小心的初值迭代，交保证低估可用——少优化、不错。缺口是交与「表达式」对象，不是再写到达的并。</p><p>与活跃：活跃后向；可用前向交。三套（活跃、到达、可用）够用到分配前；框架同一，格与方向不同。</p><h3 id="可用不是-dag-里「看见过」" tabindex="-1">可用不是 DAG 里「看见过」 <a class="header-anchor" href="#可用不是-dag-里「看见过」" aria-label="Permalink to &quot;可用不是 DAG 里「看见过」&quot;">​</a></h3><p>块内 DAG 只消块内重复。全局可用才能消跨块 CSE。不要把块内哈希当全局可用。</p><p><span class="marginnote">龙书 9.2.6 节。Appel 用可用做 CSE。代数恒等（\\(a+0\\)）是窥孔或另一格，本课只认字面同一 \\(a\\,\\mathrm{op}\\,b\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>枚举 IR 中出现过的表达式为全集的元素。算 gen/kill。交迭代。改写：若 \\(a+b\\) 在指令前可用，换成对已有临时的拷贝，再交给拷贝传播。</p>',11)),(e(),n(p,null,{default:o(()=>[c(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXPR%5B%22%E8%A1%A8%E8%BE%BE%E5%BC%8F%E5%85%A8%E9%9B%86%22%5D%20--%3E%20GK%5B%22gen%20%2F%20kill%20%E6%93%8D%E4%BD%9C%E6%95%B0%22%5D%0A%20%20GK%20--%3E%20MEET%5B%22%E5%89%8D%E5%90%91%E4%BA%A4%22%5D%0A%20%20MEET%20--%3E%20CSE%5B%22%E6%9B%BF%E6%8D%A2%E4%B8%BA%E5%B7%B2%E6%9C%89%E4%B8%B4%E6%97%B6%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>关键边：若只在部分前驱可用，可在其他前驱补算再交——那是 PRE（部分冗余），本课点名不写完。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>kill 必须随赋值精确：<code>a</code> 被写掉则 \\(a+b\\)、\\(c+a\\) 都死。别名保守：可能改到 \\(a\\) 则杀，可用变少。SSA 上操作数是名，杀更干净。不要在浮点上随便 CSE 掉含舍入的重复，若语言允许收缩；本课整数 IR 默认可消。</p><p>与<a href="/cs/reaching-def">到达</a>：到达告诉你 \\(a\\) 来自哪次写；可用告诉你 \\(a+b\\) 这个运算本身是否还在。二者常一起用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不选机器指令、不着色。不把循环不变外提写完（那要支配与回边，可用是零件）。后课默认：全局 CSE 按可用表达式做。指令选择把剩下的运算变成 ISA 模板。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可用：前向、交；操作数被写则杀。</li><li>用于全局 CSE；块内 DAG 不够跨块。</li><li>低估可用才安全。</li><li>出处：Aho et al., 龙书第 9 章。</li></ul>',8))])}const S=r(h,[["render",E]]);export{A as __pageData,S as default};
